def simplify_path(path: str) -> str:
    """
    Canonicalise an absolute Unix path.

    - Repeated slashes are collapsed.
    - "." components are removed.
    - ".." removes the previous directory component, if any.
    - "..." is treated as a normal directory/file name.
    - The result has no trailing slash, except the root path is "/".
    """
    stack = []

    for part in path.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return "/" + "/".join(stack)
