def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)

    if m == 0:
        return n
    if n == 0:
        return m

    prev = list(range(n + 1))

    for i, ca in enumerate(a, 1):
        curr = [i] + [0] * n
        for j, cb in enumerate(b, 1):
            cost = 0 if ca == cb else 1
            curr[j] = min(
                prev[j] + 1,        # delete
                curr[j - 1] + 1,    # insert
                prev[j - 1] + cost  # substitute or match
            )
        prev = curr

    return prev[n]
```

