def word_break(s: str, words: list[str]) -> bool:
    if not s:
        return True

    word_set = {w for w in words if w}
    if not word_set:
        return False

    lengths = sorted({len(w) for w in word_set})
    n = len(s)

    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for length in lengths:
            if length > i:
                break
            if dp[i - length] and s[i - length:i] in word_set:
                dp[i] = True
                break

    return dp[n]
```

